//! SQLite connection, migrations and entities.

use std::path::Path;

use sea_orm::sqlx::sqlite::{SqliteConnectOptions, SqliteJournalMode, SqlitePoolOptions};
use sea_orm::{DbErr, RuntimeErr, SqlxSqliteConnector};
use sea_orm_migration::MigratorTrait;

/// Generated by `just gen-auth`. Do not edit by hand.
#[rustfmt::skip]
#[allow(clippy::all)]
pub mod auth_schema;
mod migration;
